var A = [],
    s = [],
    B = [],
    c = [],
    r = [],
    k;

var attA = {
    name: '',
    strokeColor: '#7355ff',
    fillColor: '#7355ff'
};
A[0] = board.create('point', [2.5, -3], attA);
A[1] = board.create('point', [2, 4], attA);
A[2] = board.create('point', [-2.5, 3], attA);
A[3] = board.create('point', [-4, -2], attA);
A[4] = board.create('point', [0, -4], attA);

for (k = 0; k < 5; k++) {
    s[k] = board.create('segment', [A[k], A[(k + 2) % 5]], {
        strokeColor: 'blue',
        strokeWidth: 1
    });
}

var attB = {
    name: '',
    strokeColor: '#EA0000',
    fillColor: '#EA0000'
};
for (k = 0; k < 5; k++) {
    B[k] = board.create('intersection', [s[k], s[(k - 1 + 5) % 5], 0], attB);
}

var attC = {
    strokeColor: '#aaaaaa',
    strokeWidth: 1
};
for (k = 0; k < 5; k++) {
    c[k] = board.create('circle', [A[k], B[k], A[(k + 1) % 5]], attC);
}

var attR = {
    strokeColor: '#ff0000',
    strokeWidth: 2
};
for (k = 0; k < 5; k++) {
    r[k] = board.create('radicalaxis', [c[k], c[(k - 1 + 5) % 5]], attR);
}

var p = board.create('point', [1, 1], {
    size: 5
});

JXG.addEvent(p.rendNode, 'mouseover',
    function() {
        document.getElementById('myOutput').innerHTML = "Point " + this.name;
    },
    p);
JXG.addEvent(p.rendNode, 'mouseout',
    function() {
        document.getElementById('myOutput').innerHTML = '&nbsp;';
    },
    p);

// User can not move "A" anymore.
p.hasPoint = function() {
    return false;
};

var p2 = board.create('point', [-1, 1], {
    size: 5
});

JXG.addEvent(p2.rendNode, 'mouseover',
    function() {
        document.getElementById('myOutput').innerHTML = "Point " + this.name;
    },
    p2);

JXG.addEvent(p2.rendNode, 'mouseout',
    function() {
        document.getElementById('myOutput').innerHTML = '&nbsp;';
    },
    p2);

var getMouseCoords = function(e, i) {
        var pos = board.getMousePosition(e, i);
        return new JXG.Coords(JXG.COORDS_BY_SCREEN, pos, board);
    },

    handleDown = function(e) {
        var canCreate = true,
            i, coords, el;

        if (e[JXG.touchProperty]) {
            // index of the finger that is used to extract the coordinates
            i = 0;
        }
        coords = getMouseCoords(e, i);

        for (el in board.objects) {
            if (JXG.isPoint(board.objects[el]) && board.objects[el].hasPoint(coords.scrCoords[1], coords.scrCoords[2])) {
                canCreate = false;
                break;
            }
        }

        if (canCreate) {
            board.create('point', [coords.usrCoords[1], coords.usrCoords[2]]);
        }
    };

board.on('down', handleDown);

var p = board.create('point', [1, 1], {
    size: 5,
    fixed: true
});
p.on('over', (e) => {
    document.getElementById('myOutput').innerHTML = "Point " + p.name;
});

p.on('out', (e) => {
    document.getElementById('myOutput').innerHTML = ' ';
});

var p2 = board.create('point', [-1, 1], {
    size: 5
});
p2.on('over', function(e) {
    document.getElementById('myOutput').innerHTML = "Point " + this.name;
});
p2.on('out', function(e) {
    document.getElementById('myOutput').innerHTML = ' ';
});

var p = board.create('point', [-3, 0], {
    name: 'p'
});
var q = board.create('point', [3, 0], {
    name: 'q'
});
var pq = board.create('line', [p, q]);
var t = board.create('glider', [-2, 0, pq], {
    name: 't'
});
var txt = board.create('text', [1, 2, () => "λ = " + t.position.toFixed(2)], {
    fontSize: 24
});

// Vertical line at x=3
board.create('line', [-3, 1, 0], {
    strokeWidth: 1,
    dash: 2
});
board.create('text', [3, 8, "Default"], {
    cssClass: 'mytext'
});
board.create('text', [3, 7, "anchorX left"], {
    anchorX: 'left',
    cssClass: 'mytext'
});
board.create('text', [3, 6, "anchorX middle"], {
    anchorX: 'middle',
    cssClass: 'mytext'
});
board.create('text', [3, 5, "anchorX right"], {
    anchorX: 'right',
    cssClass: 'mytext'
});

// Horizontal line at y=2
board.create('line', [-2, 0, 1], {
    strokeWidth: 1,
    dash: 2
});
board.create('text', [1, 2, "Multiline text<br>default"], {
    cssClass: 'mytext'
});
board.create('text', [2.2, 2, "Multiline text<br>anchorY bottom"], {
    anchorY: 'bottom',
    cssClass: 'mytext'
});
board.create('text', [3.4, 2, "Multiline text<br>anchorY middle"], {
    anchorY: 'middle',
    cssClass: 'mytext'
});
board.create('text', [4.6, 2, "Multiline text<br>anchorY top"], {
    anchorY: 'top',
    cssClass: 'mytext'
});

// Horizontal line at y=2
board.create('line', [-2, 0, 1], {
    strokeWidth: 1,
    dash: 2
});
board.create('text', [3, 2, "Multiline text<br>anchorX right<br>anchorY top"], {
    anchorX: 'right',
    anchorY: 'top',
    cssClass: 'mytext'
});

board.create('text', [0.0, 0.0, 'Rotate'], {
    display: 'internal',
    rotate: 30
});

var a, b, c, d,
    f, func,
    realRoots;

a = board.create('slider', [[-8, 8], [-2.5, 8], [-10, 0, 10]], { name: 'a' });
b = board.create('slider', [[-8, 7], [-2.5, 7], [-10, -5, 10]], { name: 'b' });
c = board.create('slider', [[-8, 6], [-2.5, 6], [-10, 2, 10]], { name: 'c' });
d = board.create('slider', [[-8, 5], [-2.5, 5], [-10, 1, 10]], { name: 'd' });

f = (x) => x ** 4 + a.Value() * x ** 3 + b.Value() * x ** 2 + c.Value() * x + d.Value();
func = board.create('functiongraph', [f], { strokeWidth: 2 });

// Return all real roots of polynomial with coefficients `coeffs`
realRoots = function(coeffs) {
    return JXG.Math.Numerics.polzeros(coeffs) // Find ALL complex roots of the polynomial
        .filter((z) => Math.abs(z.imaginary) < 1.e-12) // Filter real roots
        .map((z) => z.real); // Convert complex numbers to real numbers
};

// Construct the roots.
// If the roots are non-real, they are not shown.
board.create('point', [() => realRoots([d.Value(), c.Value(), b.Value(), a.Value(), 1])[0], 0]);
board.create('point', [() => realRoots([d.Value(), c.Value(), b.Value(), a.Value(), 1])[1], 0]);
board.create('point', [() => realRoots([d.Value(), c.Value(), b.Value(), a.Value(), 1])[2], 0]);
board.create('point', [() => realRoots([d.Value(), c.Value(), b.Value(), a.Value(), 1])[3], 0]);

var A = board.create('point', [-1, -1]),
    B = board.create('point', [1, -1]),
    C = board.create('point', [0, 1]),
    alpha = board.create('angle', [B, A, C], {
        type: 'sector',
        orthoType: 'square',
        orthoSensitivity: 2,
        radius: 0.5
    }),
    beta = board.create('angle', [C, B, A], {
        type: 'sector',
        orthoType: 'sectordot',
        orthoSensitivity: 2,
        radius: 0.2
    });

var p = board.create('point', [0, 1], {
    size: 5,
    strokeColor: 'red',
    fillOpacity: 0.3,
    strokeOpacity: 0.3
});
board.create('arrow', [
    [0, 0], p
], {
    strokeWidth: 5,
    strokeOpacity: 0.7,
    strokeColor: 'blue'
});

// Start infinite animation
var i = -1;
setInterval(function() {
    p.moveTo([Math.sin(i * Math.PI * 2 / 12), Math.cos(i * Math.PI * 2 / 12)], 800);
    i++;
}, 1000);

var p = board.create('point', [1.5, 1.5], {
    size: 8,
    strokeColor: 'red',
    fillOpacity: 0.6,
    strokeOpacity: 0.6
});

board.create('segment', [
    [0, 0], p
], {
    dash: 3
});

var i, len = 25,
    p = [];

// Create points
for (i = 0; i < len; i++) {
    p[i] = board.create('point', [Math.random(), Math.random()], {
        face: 'o',
        size: 10,
        strokeColor: 'red',
        fillColor: 'red',
        fillOpacity: 0.4,
        strokeOpacity: 0.4,
        withLabel: false
    });
}
// Start animation: remove colliding points
setInterval(function() {
    var i, j;
    for (i = 0; i < p.length; i++) {
        p[i].moveTo([Math.random(), Math.random()], 1000);
    }
    i = 0;
    while (i < p.length) {
        for (j = i + 1; j < p.length; j++) {
            if (p[i].Dist(p[j]) < 0.075) {
                brd.removeObject(p[j]);
                p.splice(j, 1);
                brd.removeObject(p[i]);
                p.splice(i, 1);
                i--;
                break;
            }
        }
        i++;
    }
}, 2000);

var p0 = board.create('point', [0, 0], {
    name: 'T',
    trace: true
});
var p1 = board.create('point', [7, 5], {
    name: 'A',
    trace: true
});
var p2 = board.create('point', [5, 7], {
    name: 'B',
    trace: true
});
var l = board.create('line', [p1, p2], {
    name: ''
});

var t = board.create('transform', [function() {
    return p0.X();
}, function() {
    return p0.Y();
}], {
    type: 'translate'
});
t.bindTo([p1, p2]); // The translation is bound to the points, but the points are not updated, yet

function startAnimation() {
    p0.moveTo([-5, -8], 1500);
}

function reset() {
    p0.moveTo([0, 0]);
    p0.clearTrace();
    p1.clearTrace();
    p2.clearTrace();
}

var A = board.create('point', [-1, 0], {
    name: 'A',
    transitionDuration: 2000,
    transitionProperties: ['cx', 'cy']
});

var isPlaying = false;
var starttime = 0;
var timeElapsed = 0;
var interval;

var p = board.create('point',
    [() => Math.cos(timeElapsed), () => Math.sin(timeElapsed)]
);

function playing() {
    timeElapsed = (Date.now() - starttime) / 1000;
    board.update();
}

function play() {
    if (!isPlaying) {
        starttime = Date.now();
        isPlaying = true;
        interval = setInterval(playing, 50);
    }
}

function resetAnimation() {
    clearInterval(interval);
    timeElapsed = 0;
    isPlaying = false;
    board.update();
}

var p = [];
p.push(board.create('point', [-2, Math.random() * 5 + 5], {
    name: '',
    size: 2
}));
p.push(board.create('point', [0, 2], {
    name: '',
    size: 2
}));
p.push(board.create('point', [0.5, Math.random() * 1 + 7], {
    name: '',
    size: 2
}));

// f defines the function graph through the three points
var f = JXG.Math.Numerics.lagrangePolynomial(p);

var plot = board.create('functiongraph', [f, -3, 3]);

var s = board.create('glider', [-2, f(-2), plot], {
    name: 'drag me',
    color: 'black',
    size: 5
});
var int = board.create('integral', [
    [function() {
        return p[0].X();
    }, function() {
        return s.X();
    }], plot
], {
    fillOpacity: 0.2
});

var F = board.create('point', [function() {
    return s.X();
}, function() {
    return JXG.Math.Numerics.I([p[0].X(), s.X()], f);
}], {
    trace: true,
    name: 'F',
    fillColor: '#0000aa',
    strokeColor: '#0000aa',
    face: '[]'
});

,
    solveQ2 = function(x1, x2, x3, off) {
        var a, b, c, d;
        a = 0.5;
        b = -(x1 + x2 + x3);
        c = x1 * x1 + x2 * x2 + x3 * x3 - 0.5 * (x1 + x2 + x3) * (x1 + x2 + x3) - off;
        d = b * b - 4 * a * c;
        if (Math.abs(d) < JXG.Math.eps) {
            d = 0.0;
        }
        return [(-b + Math.sqrt(d)) / (2.0 * a), (-b - Math.sqrt(d)) / (2.0 * a)];
    };

var a = board.create('line', [[0, 0], [2, 0]], { straightFirst: false, straightLast: false, visible: false }),
    p0 = board.create('point', [0, 0], { name: '', visible: false }),
    p1 = board.create('glider', [1.3, 0, a], { name: 'drag me', showInfobox: false, label: { offset: [-20, 15] } }),

    b0 = -0.5,
    r1 = 2 - p1.X(),
    b1 = 1.0 / r1,
    r2 = (2.0 - r1),
    b2 = 1.0 / r2,

    p2 = board.create('point', [function() { return p1.X() - 2; }, 0], { name: '', visible: false }),

    c0 = board.create('circle', [p0, Math.abs(1.0 / b0)], { strokeWidth: 1, withLabel: false }),
    c1 = board.create('circle', [p1, function() { return 2 - p1.X(); }], { strokeWidth: 1, withLabel: false }),
    c2 = board.create('circle', [p2, function() { return p1.X(); }], { strokeWidth: 1, withLabel: false });

c0.curvature = function() { return b0; }; // constant
c1.curvature = function() { return 1 / (2 - p1.X()); };
c2.curvature = function() { return 1 / (p1.X()); };

var thirdCircleX = function() {
        var b0, b1, b2, x0, x1, x2, b3, bx3;
        b0 = c0.curvature();
        b1 = c1.curvature();
        b2 = c2.curvature();
        x0 = c0.midpoint.X();
        x1 = c1.midpoint.X();
        x2 = c2.midpoint.X();

        b3 = solveQ2(b0, b1, b2, 0);
        bx3 = solveQ2(b0 * x0, b1 * x1, b2 * x2, 2);
        return bx3[0] / b3[0];
    },
    thirdCircleY = function() {
        var b0, b1, b2, y0, y1, y2, b3, by3;
        b0 = c0.curvature();
        b1 = c1.curvature();
        b2 = c2.curvature();
        y0 = c0.midpoint.Y();
        y1 = c1.midpoint.Y();
        y2 = c2.midpoint.Y();

        b3 = solveQ2(b0, b1, b2, 0);
        by3 = solveQ2(b0 * y0, b1 * y1, b2 * y2, 2);
        return by3[0] / b3[0];
    },
    thirdCircleRadius = function() {
        var b0, b1, b2, b3, bx3, by3;
        b0 = c0.curvature();
        b1 = c1.curvature();
        b2 = c2.curvature();
        b3 = solveQ2(b0, b1, b2, 0);
        return 1.0 / b3[0];
    };

var p3 = board.create('point', [thirdCircleX, thirdCircleY], { name: '', visible: false }),
    c3 = board.create('circle', [p3, thirdCircleRadius], { strokeWidth: 1, withLabel: false });

c3.curvature = function() { return 1.0 / this.radius; };

var otherCirc = function(circs, level) {
    var p, c, fx, fy, fr;

    if (level <= 0) {
        return;
    }
    fx = function() {
        var b = [],
            x = [],
            i;
        for (i = 0; i < 4; i++) {
            b[i] = circs[i].curvature();
            x[i] = circs[i].midpoint.X();
        }

        b[4] = 2 * (b[0] + b[1] + b[2]) - b[3];
        x[4] = (2 * (b[0] * x[0] + b[1] * x[1] + b[2] * x[2]) - b[3] * x[3]) / b[4];
        return x[4];
    };
    fy = function() {
        var b = [],
            y = [],
            i;
        for (i = 0; i < 4; i++) {
            b[i] = circs[i].curvature();
            y[i] = circs[i].midpoint.Y();
        }

        b[4] = 2 * (b[0] + b[1] + b[2]) - b[3];
        y[4] = (2 * (b[0] * y[0] + b[1] * y[1] + b[2] * y[2]) - b[3] * y[3]) / b[4];
        return y[4];
    };
    fr = function() {
        var b = [],
            i;
        for (i = 0; i < 4; i++) {
            b[i] = circs[i].curvature();
        }
        b[4] = 2 * (b[0] + b[1] + b[2]) - b[3];
        if (isNaN(b[4])) {
            return 1000.0;
        } else {
            return 1 / b[4];
        }
    };
    p = board.create('point', [fx, fy], { name: '', visible: false });
    c = board.create('circle', [p, fr], {
        strokeWidth: 1,
        fillColor: JXG.hsv2rgb((70 * level) % 360, 0.9, 1),
        highlightFillColor: JXG.hsv2rgb((70 * level) % 360, 0.9, 0.6),
        fillOpacity: 0.7,
        withLabel: false,
    });
    c.curvature = function() { return 1 / this.radius; };

    // Recursion
    otherCirc([circs[0], circs[1], c, circs[2]], level - 1);
    otherCirc([circs[0], circs[2], c, circs[1]], level - 1);
    otherCirc([circs[1], circs[2], c, circs[0]], level - 1);
    return c;
};

//-------------------------------------------------------
var level = 3;
otherCirc([c0, c1, c2, c3], level);
otherCirc([c3, c1, c2, c0], level);
otherCirc([c0, c2, c3, c1], level);
otherCirc([c0, c1, c3, c2], level);

// Create circle through D with center M and to gliders A and B
var M = board.create('point', [0, 0], {
    name: 'M'
});
var C = board.create('point', [0, -1], {
    name: 'D'
});
var c = board.create('circle', [M, C], {
    strokeWidth: 1
});
var A = board.create('glider', [1, 0, c], {
    name: 'A'
});
var B = board.create('glider', [0, 1, c], {
    name: 'B'
});

// Determine two optimal control points
var k = function(M, A, B) {
    var ax = A.X() - M.X(),
        ay = A.Y() - M.Y(),
        bx = B.X() - M.X(),
        by = B.Y() - M.Y(),
        d, r;
    r = M.Dist(A);
    d = Math.sqrt((ax + bx) * (ax + bx) + (ay + by) * (ay + by));
    if (JXG.Math.Geometry.rad(A, M, B) > Math.PI) {
        d *= -1;
    }

    if (Math.abs(by - ay) > JXG.Math.eps) {
        return (ax + bx) * (r / d - 0.5) * 8.0 / 3.0 / (by - ay);
    } else {
        return (ay + by) * (r / d - 0.5) * 8.0 / 3.0 / (ax - bx);
    }
};

var P1 = board.create('point', [
    () => A.X() - k(M, A, B) * (A.Y() - M.Y()),
    () => A.Y() + k(M, A, B) * (A.X() - M.X())
], {
    color: 'blue'
});
var P2 = board.create('point', [
    () => B.X() + k(M, A, B) * (B.Y() - M.Y()),
    () => B.Y() - k(M, A, B) * (B.X() - M.X())
], {
    color: 'blue'
});

// Create the Bezier segment
var b = board.create('curve', JXG.Math.Numerics.bezier([A, P1, P2, B]), {
    strokecolor: 'black',
    strokeOpacity: 1,
    strokeWidth: 3
});

var l1 = board.create('segment', [A, P1], {
    dash: 2
});
var l2 = board.create('segment', [B, P2], {
    dash: 2
});

var n = board.create('slider', [
    [1, 3],
    [6, 3],
    [1, 10, 70]
], {
    name: 'n',
    snapWidth: 1
});

// Fixed function term
var f = function(x) {
    return 0.2 * x * x + 2.0 * Math.sin(x);
}
var plot = board.create('functiongraph', [f], {
    strokeWidth: 1,
    strokeOpacity: 0.3
});

// Plot dashed horizontal and vertical lines 
var start = -3.0;
var end = 5.0;
var sc = board.create('curve', [
    [0],
    [0]
], {
    dash: 1,
    strokeWidth: 1,
    strokeColor: 'red'
});
board.updateDataArray = function() {
    var i;
    var m = n.Value();
    var d = (end - start) / m;
    this.dataX = [];
    this.dataY = [];
    this.dataX[0] = start;
    this.dataY[0] = f(start);
    for (i = 1; i <= m; i++) {
        this.dataX.push(start + i * d);
        this.dataY.push(f(start + (i - 1) * d));
        this.dataX.push(start + i * d);
        this.dataY.push(f(start + i * d));
    }
}
// Plot secants
var approx = board.create('curve', [
    [0],
    [0]
], {
    strokeColor: 'red'
});
approx.updateDataArray = function() {
    var i;
    var m = n.Value();
    var d = (end - start) / m;
    this.dataX = [];
    this.dataY = [];
    this.dataX[0] = start;
    this.dataY[0] = f(start);
    for (i = 1; i <= m; i++) {
        this.dataX.push(start + i * d);
        this.dataY.push(f(start + i * d));
    }
}

board.create('text', [-7, 1, function() {
    var i, s, f0, f1;
    var m = n.Value();
    var d = (end - start) / m;
    s = 0.0;
    f0 = f(start);
    for (i = 1; i <= m; i++) {
        f1 = f(start + i * d);
        s += Math.sqrt(d * d + (f1 - f0) * (f1 - f0));
        f0 = f1;
    }
    return 'Length = ' + s.toFixed(4);
}], {
    fontSize: 24
});
board.update();

var c, i, count = 0,
    tin = 0,
    tout = 0,
    p = [],
    updateText;
var c = board.create('circle', [
    [0, 0], 1
]);

p = [];
for (var i = 0; i < 50; i++) {
    p[i] = board.create('point',
        [function() {
            return 2 * Math.random() - 1;
        }, function() {
            return 2 * Math.random() - 1;
        }], {
            name: ' ',
            withLabel: false
        });
}

updateText = function() {
    var i, inp, outp, x, y, text = '';
    count++;

    inp = 0;
    outp = 0;

    for (i = 0; i < p.length; i++) {
        x = p[i].X();
        y = p[i].Y();

        if (x * x + y * y <= 1) {
            inp++;
        } else {
            outp++;
        }
    }
    tin += inp;
    tout += outp;

    text += '<b>Current:</b><br />in: ' + inp + ', out: ' + outp + ', total: ' + (inp + outp) +
