function compareM(m) {
    let b = true;
    for (let i = 0; i < 3; i++)
        for (let j = 0; j < 3; j++) {
            if (superM[m][i][j] == 0) {
                if (initSuperM[m][i][j] != 0)
                    b = false;
            } else {
                if (initSuperM[m][i][j] == 0)
                    b = false;
            }
        }
    return b;
}

function copyS() {
    copyM(initSuperM['top'], topP());
    copyM(initSuperM['north'], northP());
    copyM(initSuperM['south'], southP());
    copyM(initSuperM['west'], westP());
    copyM(initSuperM['east'], eastP());
    copyM(initSuperM['base'], baseP());
}

